import numpy as np


class RefinedMixedFeasibilityEAv3:
    """
    Feasibility-rule (mu+lambda) ES for mixed-integer constrained black-box problems.
    - Deb feasibility rules (feasible < infeasible; infeasible by violation; feasible by objective).
    - Cached evaluator: duplicate points are never re-evaluated.
    - Feasible elite archive: best distinct feasible points are kept for restarts.
    - Restarts cycle through sigma levels around archive elites; every third restart is random.
    - Pattern-search polish of the best feasible point with step growth on success and
      random-direction probes in the continuous subspace.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng(np.random.randint(0, 2**31 - 1))
        dim = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        vtypes = list(func.variable_types)
        int_mask = np.array([vtypes[i] != "continuous" for i in range(dim)])
        cont_idx = np.where(~int_mask)[0]
        int_idx = np.where(int_mask)[0]
        n_int = np.ones(dim, dtype=int)
        for i in int_idx:
            n_int[i] = int(func.n_values[i])
        span = ub - lb
        span[span <= 0] = 1.0
        budget = self.budget

        st = {"evals": 0, "best_f": np.inf, "best_x": None, "best_any": None}
        cache = {}
        archive = []  # list of feasible individuals, sorted by f
        ARCH_MAX = 8

        def repair(x):
            x = np.clip(x, lb, ub)
            if len(int_idx) > 0:
                x[int_idx] = np.clip(np.round(x[int_idx]), 0, n_int[int_idx] - 1)
            return x

        def add_archive(ind):
            kk = tuple(ind["x"].tolist())
            for a in archive:
                if tuple(a["x"].tolist()) == kk:
                    return
            archive.append(ind)
            archive.sort(key=lambda a: a["key"])
            del archive[ARCH_MAX:]

        def evaluate(x):
            x = repair(np.asarray(x, dtype=float))
            k = tuple(x.tolist())
            if k in cache:
                return cache[k]
            if st["evals"] >= budget:
                return None
            f, g = func(x)
            st["evals"] += 1
            g = np.atleast_1d(np.asarray(g, dtype=float))
            v = float(np.sum(np.maximum(np.nan_to_num(g, nan=1.0, posinf=1e10), 0.0)))
            f = float(f)
            if not np.isfinite(f):
                f = np.inf
            if v == 0.0 and not np.isfinite(f):
                v = 1.0
            key = (0.0, f) if v == 0.0 else (1.0, v)
            ind = {"key": key, "x": x.copy()}
            cache[k] = ind
            if v == 0.0 and f < st["best_f"]:
                st["best_f"] = f
                st["best_x"] = x.copy()
            if v == 0.0 and np.isfinite(f):
                add_archive(ind)
            if st["best_any"] is None or key < st["best_any"]["key"]:
                st["best_any"] = ind
            return ind

        def random_point():
            x = np.empty(dim)
            x[cont_idx] = rng.uniform(lb[cont_idx], ub[cont_idx])
            x[int_idx] = rng.integers(0, n_int[int_idx])
            return x

        def mutate(x, sigma, pm):
            y = x.copy()
            mask = rng.random(dim) < pm
            if not mask.any():
                mask[rng.integers(dim)] = True
            for i in np.where(mask)[0]:
                if int_mask[i]:
                    if n_int[i] <= 1:
                        continue
                    if vtypes[i] == "ordinal":
                        if rng.random() < 0.75:
                            y[i] = y[i] + (1 if rng.random() < 0.5 else -1)
                        else:
                            y[i] = rng.integers(0, n_int[i])
                    elif vtypes[i] == "binary":
                        y[i] = 1 - y[i]
                    else:
                        cur = int(round(y[i]))
                        choices = [c for c in range(n_int[i]) if c != cur]
                        y[i] = choices[rng.integers(len(choices))]
                else:
                    if rng.random() < 0.1:
                        step = rng.standard_cauchy() * sigma * span[i] * 0.5
                    else:
                        step = rng.normal() * sigma * span[i]
                    y[i] = y[i] + step
            return repair(y)

        def crossover(a, b):
            m = rng.random(dim) < 0.5
            return np.where(m, a, b)

        def tournament(pop, k=2):
            idx = rng.integers(len(pop), size=k)
            best = min(idx, key=lambda j: pop[j]["key"])
            return pop[best]

        def pattern_search(ind):
            best = ind
            step = 0.1
            while st["evals"] < budget and step > 1e-3:
                improved = False
                # continuous coordinate moves with step growth on success
                for i in rng.permutation(cont_idx):
                    for sgn in (1.0, -1.0):
                        y = best["x"].copy()
                        y[i] = y[i] + sgn * step * span[i]
                        c = evaluate(y)
                        if c is None:
                            return best
                        if c["key"] < best["key"]:
                            best = c
                            improved = True
                            step = min(step * 1.5, 0.5)
                            break
                # integer coordinate moves
                for i in rng.permutation(int_idx):
                    if n_int[i] <= 1:
                        continue
                    if vtypes[i] == "ordinal":
                        cands = [best["x"][i] - 1, best["x"][i] + 1]
                    elif vtypes[i] == "binary":
                        cands = [1 - best["x"][i]]
                    else:
                        cur = int(round(best["x"][i]))
                        others = [c for c in range(n_int[i]) if c != cur]
                        if len(others) > 3:
                            others = list(rng.choice(others, size=3, replace=False))
                        cands = others
                    for cv in cands:
                        y = best["x"].copy()
                        y[i] = cv
                        c = evaluate(y)
                        if c is None:
                            return best
                        if c["key"] < best["key"]:
                            best = c
                            improved = True
                            break
                # random-direction probes in continuous subspace
                if len(cont_idx) > 0:
                    for _ in range(2):
                        d = rng.normal(size=len(cont_idx))
                        nrm = np.linalg.norm(d)
                        if nrm < 1e-12:
                            continue
                        d /= nrm
                        y = best["x"].copy()
                        y[cont_idx] = y[cont_idx] + step * span[cont_idx] * d
                        c = evaluate(y)
                        if c is None:
                            return best
                        if c["key"] < best["key"]:
                            best = c
                            improved = True
                            step = min(step * 1.5, 0.5)
                            break
                if not improved:
                    step *= 0.5
            return best

        mu = 15
        lam = 30
        searched_keys = set()
        restart_count = 0

        while st["evals"] < budget:
            restart_count += 1
            pop = []
            elite_mode = len(archive) > 0 and (restart_count % 3 != 0)
            if elite_mode:
                # rank-biased choice among archive elites
                w = np.array([0.5 ** r for r in range(len(archive))])
                w /= w.sum()
                base_ind = archive[rng.choice(len(archive), p=w)]
                level = restart_count % 3
                sigma = [0.1, 0.03, 0.2][level]
                pop.append(base_ind)
                for _ in range(mu - 1):
                    if st["evals"] >= budget:
                        break
                    c = evaluate(mutate(base_ind["x"], sigma * 1.5, 0.3))
                    if c is not None:
                        pop.append(c)
            else:
                sigma = 0.2
                if st["best_any"] is not None:
                    pop.append(st["best_any"])
            while len(pop) < mu and st["evals"] < budget:
                c = evaluate(random_point())
                if c is None:
                    break
                pop.append(c)
            if not pop:
                break
            pop.sort(key=lambda ind: ind["key"])
            last_key = pop[0]["key"]
            stagn = 0
            G = 25

            while st["evals"] < budget and stagn < G:
                children = []
                successes = 0
                pm = 1.0 / dim
                for _ in range(lam):
                    if st["evals"] >= budget:
                        break
                    parent = tournament(pop)
                    base = parent["x"]
                    if rng.random() < 0.3:
                        other = tournament(pop)
                        base = crossover(base, other["x"])
                    child = evaluate(mutate(base, sigma, pm))
                    if child is None:
                        break
                    children.append(child)
                    if child["key"] < parent["key"]:
                        successes += 1
                if not children:
                    break
                pop = sorted(pop + children, key=lambda ind: ind["key"])
                uniq, seen = [], set()
                for ind in pop:
                    kk = tuple(ind["x"].tolist())
                    if kk in seen:
                        continue
                    seen.add(kk)
                    uniq.append(ind)
                pop = uniq[:mu]

                rate = successes / max(1, len(children))
                if rate > 0.2:
                    sigma *= 1.22
                elif rate < 0.2:
                    sigma *= 0.82
                sigma = float(np.clip(sigma, 1e-4, 0.5))

                if pop[0]["key"] < last_key:
                    improved_sig = (pop[0]["key"][0] != last_key[0]) or (
                        pop[0]["key"][1] < last_key[1] - 1e-10 * (1 + abs(last_key[1])))
                    stagn = 0 if improved_sig else stagn + 1
                    last_key = pop[0]["key"]
                else:
                    stagn += 1

            # polish best feasible point found so far
            if st["best_x"] is not None and st["evals"] < budget:
                bk = tuple(repair(st["best_x"]).tolist())
                if bk not in searched_keys:
                    searched_keys.add(bk)
                    pattern_search(cache[bk])

        if st["best_x"] is None:
            if st["best_any"] is not None:
                return st["best_f"], st["best_any"]["x"]
            return np.inf, None
        return st["best_f"], st["best_x"]
